import{z as n,x as s,o as E,c as B,q as D,j as o,D as e,d as t,s as l,S as i,b as A}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"存储器光刻：DRAM 与 NAND","description":"","frontmatter":{"title":"存储器光刻：DRAM 与 NAND","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/memory-litho-dram-nand.md","filePath":"litho/memory-litho-dram-nand.md","lastUpdated":1791413859000}'),d={name:"litho/memory-litho-dram-nand.md"};function N(p,a,m,h,R,u){const r=s("Mermaid");return E(),B("div",null,[a[2]||(a[2]=D('<h1 id="存储器光刻-dram-与-nand" tabindex="-1">存储器光刻：DRAM 与 NAND <a class="header-anchor" href="#存储器光刻-dram-与-nand" aria-label="Permalink to &quot;存储器光刻：DRAM 与 NAND&quot;">​</a></h1><div class="epigraph"><p>DRAM 仍在平面上挤半节距，浸没 + 多重是主路径；3D NAND 把负担交给深孔刻蚀，光刻更多是对准与台阶。</p><footer>—— 对照 DRAM 与 3D NAND 图形化负担转移的公开论述</footer></div><p><a href="/litho/foundry-roadmap-compare">上一课</a>对比逻辑代工。缺口是存储。本课钉 DRAM 与 NAND 的光刻角色。3D NAND 负担如何具体转移，留给<a href="/litho/3d-nand-litho-shift">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DRAM：电容与字线/位线在平面周期上，ArF 浸没加 SADP/SAQP、套刻极严，EUV 插入是成本交叉问题，阵列周期性对掩模 CDU 与热点极敏感。NAND：3D 堆叠后，关键变成沟道孔、台阶、字线切割的深宽比刻蚀与沉积，光刻分辨率压力相对逻辑/DRAM 平面密线不同。</p><p>缺口是<strong>产品类改瓶颈机台</strong>，不是同一套 CPP 故事。把存储 capex 也写成「全是 EUV」，会错。</p><p><span class="marginnote">可以把 DRAM 与 3D NAND 的差别想成&quot;平房里加挤&quot;与&quot;盖楼&quot;：DRAM 还是在一块地基上把房间隔得更细（平面节距），3D NAND 则是往上叠楼层，难点变成把电梯井（沟道孔）打穿所有楼层还要打直——那是刻蚀的活，不是光刻分辨率的活。</span></p><h3 id="阵列-vs-外围" tabindex="-1">阵列 vs 外围 <a class="header-anchor" href="#阵列-vs-外围" aria-label="Permalink to &quot;阵列 vs 外围&quot;">​</a></h3><p>DRAM/NAND 外围逻辑仍可能走类似逻辑的金属光刻；阵列才是产品特征。规划要拆。</p><p><span class="marginnote">存储厂的浸没台数与逻辑厂 mix 完全不同，交叉模型要换输入。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分阵列/外围列层策略。DRAM 盯半节距与套刻；NAND 盯孔 AR、对准、键合（若有）。EUV 对 DRAM 的交叉按公开插入叙事理解，不编层数。</p>',12)),(E(),o(i,null,{default:e(()=>[l(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20LAYERS%5B%22%E5%B1%82%E5%88%86%E4%B8%A4%E7%B1%BB%22%5D%20--%3E%20ARRAY%5B%22%E9%98%B5%E5%88%97%E5%B1%82%3A%20%E4%BA%A7%E5%93%81%E7%89%B9%E5%BE%81%22%5D%0A%20%20LAYERS%20--%3E%20PERI%5B%22%E5%A4%96%E5%9B%B4%E5%B1%82%3A%20%E7%B1%BB%E4%BC%BC%E9%80%BB%E8%BE%91%22%5D%0A%20%20ARRAY%20--%3E%20DRAMA%5B%22DRAM%3A%20%E5%8D%8A%E8%8A%82%E8%B7%9D%20%2B%20%E5%A5%97%E5%88%BB%20%2B%20CDU%20%E6%95%8F%E6%84%9F%22%5D%0A%20%20ARRAY%20--%3E%20NANDA%5B%22NAND%3A%20%E6%B7%B1%E5%AD%94%E5%AF%B9%E5%87%86%20%2B%20%E5%8F%B0%E9%98%B6%22%5D%0A%20%20PERI%20--%3E%20LOGIC%5B%22%E6%B5%B8%E6%B2%A1%E5%A4%9A%E9%87%8D%20%E6%88%96%20EUV%20%E6%8C%89%E6%88%90%E6%9C%AC%22%5D%0A%20%20DRAMA%20--%3E%20PLAN%5B%22%E6%8E%92%E4%BA%A7%E4%B8%8E%20capex%20%E5%88%86%E5%BC%80%E7%AE%97%22%5D%0A%20%20NANDA%20--%3E%20PLAN%0A%20%20LOGIC%20--%3E%20PLAN%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A("h2",{id:"机制",tabindex:"-1"},[t("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=A("p",null,"比特密度：DRAM 靠平面 F²；NAND 靠层数 × 平面孔密度。后者让刻蚀/薄膜的边际回报在一段时间内高于缩孔节距。光刻仍定义孔位置与套刻，但不总是分辨率英雄。",-1)),a[5]||(a[5]=A("p",null,[A("span",{class:"marginnote"},'\\(F\\) 指半节距，DRAM 单元面积按 \\(F^2\\) 计（经典 1T1C 单元约几倍 \\(F^2\\)）。半节距每缩一步，单元面积近似按平方缩小——平面 DRAM 的全部密度压力都从"继续缩小 F"来，这也是它对 CDU 与套刻比逻辑更敏感的根源。')],-1)),a[6]||(a[6]=A("p",null,[A("span",{class:"marginnote"},'常见误区是"存储厂一定最先上 EUV"。实际上 NAND 靠加层就能加密度，EUV 收益低；DRAM 才在节距挤不动时按成本交叉考虑 EUV。所以两家的浸没与 EUV 台数 mix 完全不同，交叉模型不能共用一份输入。')],-1)),(E(),o(i,null,{default:e(()=>[l(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20DRAM%5B%22DRAM%20%E9%98%B5%E5%88%97%22%5D%20--%3E%20PITCH%5B%22%E5%B9%B3%E9%9D%A2%E8%8A%82%E8%B7%9D%20%2B%20%E5%A4%9A%E9%87%8D%20%2F%20EUV%22%5D%0A%20%20NAND%5B%223D%20NAND%22%5D%20--%3E%20ETCH%5B%22%E6%B7%B1%E5%AD%94%20%2F%20%E5%8F%B0%E9%98%B6%E5%88%BB%E8%9A%80%22%5D%0A%20%20NAND%20--%3E%20LITH%5B%22%E5%AD%94%E4%BD%8D%E7%BD%AE%20%E5%AF%B9%E5%87%86%20%E5%8F%B0%E9%98%B6%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=D('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不给各厂堆叠层数当永远数。不把 DRAM EUV 插入当已完成或永不。本课不展开电容介质物理。</p><p>后课默认：NAND 的主墙在刻蚀；下一课专门写光刻负担如何转移。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DRAM：平面节距与套刻，浸没多重/EUV 交叉。</li><li>3D NAND：分辨率压力让位于深孔刻蚀，光刻管位置与台阶。</li><li>阵列与外围策略不同。</li><li>出处：DRAM/NAND 图形化负担的公开论述。</li></ul>',5))])}const P=n(d,[["render",N]]);export{f as __pageData,P as default};
